import pandas as pd

def classify_triangles(triangles: pd.DataFrame) -> pd.DataFrame:
    def classify(row):
        a, b, c = row['A'], row['B'], row['C']
        if a + b <= c or a + c <= b or b + c <= a:
            return 'Not A Triangle'
        if a == b == c:
            return 'Equilateral'
        if a == b or b == c or a == c:
            return 'Isosceles'
        return 'Scalene'

    res = triangles.copy()
    res['triangle_type'] = res.apply(classify, axis=1)
    return res[['triangle_type']]
